void coldRoom(const CombatContent& c,const SessionEntry& base){
 need(c.catalog.value("cold_room_revision",std::string{})=="g3-cold-room-v1","Cold correction not explicitly enabled");
 const std::array<std::array<int,5>,9> rows{{{5,5,9,0,2},{6,5,8,0,1},{7,7,6,1,3},{8,7,9,1,1},{9,7,7,1,2},{10,5,6,0,3},{11,14,9,1,3},{12,14,7,0,1},{16,7,8,0,0}}};
 for(const auto& row:rows){const auto id="m172-e"+std::to_string(row[0]);const auto& o=c.objects.at(id);const auto& v=o.variants.at(0).definition;
  need(o.tile==TilePosition{row[1],row[2]}&&o.variants.size()==1&&v.spriteId=="g3-cold-corpse-"+std::to_string(row[3])&&v.direction==directionName(static_cast<Direction>(row[4]))&&v.initialColumn==1&&v.animationType==4&&v.layer==1&&!v.overlapForbidden&&v.trigger==0,"Changed original corpse pose/layer");
  const auto flow=id+"-p1";need(c.catalog["flows"].contains(flow)==(row[0]!=16),"Zero-command corpse lost or invented interaction");
  TilePosition tile{o.tile.x,o.tile.y+1};Direction face=Direction::Up;
  for(const auto [dx,dy,d]:{std::tuple{0,1,Direction::Up},std::tuple{0,-1,Direction::Down},std::tuple{1,0,Direction::Left},std::tuple{-1,0,Direction::Right}}){const TilePosition candidate{o.tile.x+dx,o.tile.y+dy};const bool occupied=std::any_of(rows.begin(),rows.end(),[&](const auto& r){return candidate==TilePosition{r[1],r[2]};});if(!occupied){tile=candidate;face=d;break;}}
  auto e=entry(c,base,172,tile);e.direction=face;GameSession s(c.items,e.session,c.facts);CombatScene scene(c,s,e,safe);scene.update({});
  const auto& actor=findCharacter(scene.world(),id);need(actor.active&&!actor.through&&actor.animation.column()==1&&actor.graphicFacing()==static_cast<Direction>(row[4]),"Static source corpse hidden/animated");
  need(!scene.world().canPlayerMove(face),"Source corpse no longer blocks");
  if(row[0]==16){scene.update(key());need(!scene.dialogue().active(),"Zero-command corpse invented dialogue");continue;}
  const auto& m=c.messages.at(flow+"-c5").message;need(m.lines.size()==3&&m.lines[0].raw=="\\>"&&m.lines[1].raw=="\\>"&&m.lines[2].raw==localSourceText("g3_access_checks.1")&&m.display.transparent&&!m.display.continueEvents,"Cold source controls/options changed");
  const int hp=s.hp(),phase=s.variable(387);const bool x=s.flag(469),y=s.flag(470),z=s.flag(471);scene.update(key());need(scene.dialogue().active()&&!s.flag(1)&&!s.flag(18),"Public cold investigation/control locks missing");settle(scene);need(s.flag(1)&&s.flag(18)&&s.hp()==hp&&s.variable(387)==phase&&s.flag(469)==x&&s.flag(470)==y&&s.flag(471)==z,"Investigation lost cleanup or changed access facts");
 }
 auto e=entry(c,base,172,{12,10});GameSession s(c.items,e.session,c.facts);CombatScene scene(c,s,e,safe);scene.update({});const auto cues=scene.takePresentation();need(std::any_of(cues.begin(),cues.end(),[](const auto& event){return event.id=="m172-e4-p1-c1";}),"Cold fog not emitted");need(!findCharacter(scene.world(),"m172-e4").active&&scene.foreground()==ForegroundKind::None,"Cold fog did not erase its scene event");scene.update({});const auto repeated=scene.takePresentation();need(std::none_of(repeated.begin(),repeated.end(),[](const auto& event){return event.id=="m172-e4-p1-c1";}),"Erased cold fog repeated");
 need(c.cue("m172-e4-p1-c1")["transparency_percent"]==60,"Original fog transparency changed");
 std::cout<<"Cold nine source poses/blocking, eight public investigations/controls/cleanup, zero-command body and fog once passed; unchanged save identity="<<c.compatibility<<'\n';
}
void coldRejections(const std::filesystem::path& package,const std::filesystem::path& root){
 const auto wrapper=nlohmann::json::parse(read(package.c_str()));std::filesystem::create_directories(root);
 for(const std::string kind:{"unknown-revision","unknown-field","path","missing","corrupt","symlink","recursive","base-corrupt","base-projection"}){
  const auto dir=root/kind;std::filesystem::create_directories(dir);auto d=wrapper;
  for(const auto* name:{"g3-cold-corpse-0.png","g3-cold-corpse-1.png"}){std::filesystem::copy_file(package.parent_path()/name,dir/name,std::filesystem::copy_options::overwrite_existing);}
  std::string expected;
  if(kind=="unknown-revision"){d["resource_revision"]="g3-cold-room-v2";expected="Unknown G3 resource revision";}
  if(kind=="unknown-field"){d["extra"]=true;expected="Unknown G3 resource revision";}
  if(kind=="path"){d["source"]["file"]="../cold-room-base.json";expected="Invalid cold revision source";}
  if(kind=="missing"){std::filesystem::remove(dir/"g3-cold-corpse-0.png");expected="Missing G3 resource";}
  if(kind=="corrupt"){std::ofstream(dir/"g3-cold-corpse-0.png")<<"bad";expected="Changed G3 source/media";}
  if(kind=="symlink"){std::filesystem::remove(dir/"g3-cold-corpse-0.png");std::filesystem::create_symlink(package.parent_path()/"g3-cold-corpse-0.png",dir/"g3-cold-corpse-0.png");expected="Missing G3 resource";}
  if(kind=="recursive"){const auto raw=wrapper.dump();std::ofstream(dir/"cold-room-base.json")<<raw;d["source"]["sha256"]=contentSha256(raw);expected="Recursive cold revision";}
  if(kind=="base-corrupt"){std::ofstream(dir/"cold-room-base.json")<<"bad";expected="Changed G3 source/media";}
  if(kind=="base-projection"){auto base=nlohmann::json::parse(read((package.parent_path()/"cold-room-base.json").c_str()));base["projection"]["facts"]["9999"]="bad";const auto raw=base.dump();std::ofstream(dir/"cold-room-base.json")<<raw;d["source"]["sha256"]=contentSha256(raw);expected="Unreviewed G3 projection";}
  std::ofstream(dir/"g3.json")<<d.dump();bool refused=false;try{loadCombatContent(dir/"g3.json");}catch(const std::exception& e){refused=std::string(e.what()).find(expected)!=std::string::npos;std::cout<<kind<<" rejected: "<<e.what()<<'\n';}need(refused,"Cold malformed revision was not precisely rejected: "+kind);
 }
}

